const $ = s => document.querySelector(s);
const TOKEN_KEY = 'relaydesk_token';
const REFRESH_KEY = 'relaydesk_refresh_token';
const state = {page:'overview',data:null,activeConversation:null,lastAnswer:null,knowledgeSearch:'',glossarySearch:''};
const languages = [['en','English','EN'],['es','Spanish','ES'],['fr','French','FR'],['de','German','DE'],['pt','Portuguese','PT'],['it','Italian','IT'],['zh','Chinese','中文'],['ja','Japanese','日本'],['ko','Korean','한국'],['ar','Arabic','العربية'],['hi','Hindi','HI'],['nl','Dutch','NL'],['sv','Swedish','SV'],['no','Norwegian Bokmål','NO'],['tr','Turkish','TR'],['pl','Polish','PL'],['ru','Russian','RU'],['id','Indonesian','ID'],['th','Thai','TH'],['vi','Vietnamese','VI']];
const icons={overview:'◫',inbox:'▤',assistant:'✳',knowledge:'▧',glossary:'文',channels:'⌘',languages:'◎',analytics:'▥',tests:'✓',growth:'↗',settings:'⚙'};
const titleMap={overview:'Overview',inbox:'Inbox',assistant:'AI assistant',knowledge:'Knowledge base',glossary:'Terminology',channels:'Channels',languages:'Languages',analytics:'Analytics',tests:'Quality & tests',growth:'Seller briefings',settings:'Settings'};
async function api(url,opts={}){
  const headers={'content-type':'application/json',...(opts.headers||{})};
  const token=localStorage.getItem(TOKEN_KEY);
  if(token && !headers.authorization && !headers.Authorization) headers.authorization=`Bearer ${token}`;
  const r=await fetch(url,{...opts,headers});
  const data=await r.json().catch(()=>({}));
  if(!r.ok){
    const error=new Error(data.error||`Request failed (${r.status})`);
    error.status=r.status;
    if(r.status===401){ localStorage.removeItem(TOKEN_KEY); error.auth=true; }
    throw error;
  }
  return data;
}
function authGate(message=''){
  $('#pageCrumb').textContent='Sign in';
  $('#page').innerHTML=`<div class="card card-pad auth-gate" style="max-width:520px;margin:36px auto">
    <div class="eyebrow">RELAYDESK WORKSPACE</div>
    <h1 style="margin:6px 0 8px">商家登录 / Merchant sign in</h1>
    <p class="muted">登录商家工作台后访问 Inbox、Knowledge base 和 Languages；未登录时菜单会保留在此登录页。</p>
    <p class="muted" style="font-size:11px">Sign in to access the workspace. No API key is exposed in the browser.</p>
    <form id="dashboardLoginForm" style="margin-top:18px">
      <label for="dashboardEmail">邮箱 / Email</label>
      <input id="dashboardEmail" type="email" autocomplete="username" placeholder="you@example.com" required>
      <label for="dashboardPassword" style="margin-top:12px;display:block">密码 / Password</label>
      <input id="dashboardPassword" type="password" autocomplete="current-password" placeholder="至少 6 位 / at least 6 characters" minlength="6" required>
      <button class="btn primary" type="submit" style="width:100%;margin-top:14px">登录 / Sign in</button>
    </form>
    <p id="dashboardLoginError" class="error" role="alert">${esc(message)}</p>
    <p style="margin-top:14px;font-size:11px" class="muted">还没有账号？<a href="/onboarding.html">注册商家 / Create account</a></p>
  </div>`;
  const form=$('#dashboardLoginForm');
  if(form) form.onsubmit=async (event)=>{
    event.preventDefault();
    const email=$('#dashboardEmail').value.trim();
    const password=$('#dashboardPassword').value;
    const errorEl=$('#dashboardLoginError');
    errorEl.textContent='';
    try{
      const response=await fetch('/api/v1/auth/login',{
        method:'POST',
        headers:{'content-type':'application/json'},
        body:JSON.stringify({email,password})
      });
      const data=await response.json().catch(()=>({}));
      if(!response.ok) throw new Error(data.error||`Login failed (${response.status})`);
      if(!data.access_token && !data.token) throw new Error('Login response did not include a token.');
      localStorage.setItem(TOKEN_KEY,data.access_token||data.token);
      if(data.refresh_token) localStorage.setItem(REFRESH_KEY,data.refresh_token);
      await reload();
      toast('已登录 / Signed in.');
    }catch(error){
      errorEl.textContent=error.message||'Login failed.';
    }
  };
  wirePage();
}

function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3200);}
function fmtPct(n){return `${Math.round((Number(n)||0)*100)}%`;}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">RELAYDESK WORKSPACE</div><h1>${title}</h1><p>${sub}</p></div><div class="heading-actions">${actions}</div></div>`;}
function cardHead(title,sub='',right=''){return `<div class="card-head"><div><h3>${title}</h3>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`;}
function stat(label,value,foot,icon='✳',cls=''){return `<div class="card stat-card"><div class="stat-label"><span>${label}</span><span class="stat-icon">${icon}</span></div><div class="stat-value ${cls}">${value}</div><div class="stat-foot">${foot}</div></div>`;}
function badge(text,cls=''){return `<span class="badge ${cls}">${text}</span>`;}
function btn(text,action,primary=false,extra=''){return `<button class="btn ${primary?'primary':''} ${extra}" data-action="${action}">${text}</button>`;}
function bars(vals,labels){return `<div class="mini-bars">${vals.map((v,i)=>`<div class="mini-bar-col"><div class="mini-bar ${i===vals.length-1?'hot':''}" style="height:${Math.max(6,v)}%"></div><small>${labels[i]}</small></div>`).join('')}</div>`;}
function getActiveConv(){return state.data?.conversations?.find(c=>c.id===state.activeConversation)||state.data?.conversations?.[0];}
function render(){if(!state.data){authGate();return;}$('#storeNameSide').textContent=state.data.settings.storeName||'My store';$('#openCount').textContent=state.data.conversations.filter(c=>c.status==='open').length;$('#pageCrumb').textContent=titleMap[state.page]||'Overview';document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));$('#page').innerHTML=pages[state.page]();wirePage();}
function profileCard(){const p=state.data.profile||{};const actions=Array.isArray(p.ai_actions)?p.ai_actions:[];return `<div class="card card-pad" style="margin-bottom:18px">${cardHead('经营概况','AI 军师上下文：客单价、核心品类、目标市场')}<form id="profileForm"><div class="form-row"><div class="field"><label>店铺 / 品牌</label><input name="business_name" value="${esc(p.business_name||'')}"></div><div class="field"><label>客单价 / 月营收</label><input name="monthly_revenue" value="${esc(p.monthly_revenue||'')}" placeholder="如 客单价 $35 / 月营收 $50k"></div></div><div class="form-row"><div class="field"><label>核心品类</label><input name="categories" value="${esc(p.categories||'')}" placeholder="如 家居、宠物用品"></div><div class="field"><label>目标市场（逗号分隔）</label><input name="markets" value="${esc((p.markets||[]).join(', '))}" placeholder="US, EU, JP"></div></div><div class="form-row"><div class="field"><label>经营平台（逗号分隔）</label><input name="platforms" value="${esc((p.platforms||[]).join(', '))}" placeholder="Amazon, Shopify"></div><div class="field"><label>团队规模</label><input name="team_size" type="number" min="0" value="${p.team_size??''}"></div></div><div class="field"><label>当前目标</label><textarea name="goals" rows="2" placeholder="如 3 个月内把 ACOS 压到 25% 以下">${esc(p.goals||'')}</textarea></div><div style="display:flex;gap:8px"><button class="btn primary" type="submit">保存经营档案</button><button class="btn" type="button" id="profileAnalyze">AI 诊断</button></div></form><div id="profileAi" style="margin-top:12px">${p.ai_summary?`<div class="notice"><div class="notice-icon">✦</div><div><strong>AI 诊断：</strong>${esc(p.ai_summary)}${actions.length?`<ul>${actions.map(a=>`<li>${esc(a)}</li>`).join('')}</ul>`:''}</div></div>`:''}</div></div>`;}
const pages={
overview(){const s=state.data.stats;return `${heading('Good morning 👋','Here’s how your customer support is performing today.',`${btn('Run quality check','run-tests')} ${btn('+ Add knowledge','goto-knowledge',true)}`)}<div class="stats-grid">${stat('AI replies generated',s.answers,'Across your workspace','✳')}${stat('Evidence-backed answers',fmtPct(s.groundedRate),'Answers with knowledge matches','▧','')}${stat('Human handoff rate',fmtPct(s.handoffRate),'Low confidence or unsupported','↗')}${stat('Knowledge articles',s.knowledgeCount,'Store-approved source content','▤')}</div><div class="grid-2"><div class="card card-pad">${cardHead('Support activity','Illustrative daily trend · live events appear after use',`<span class="badge green">Live workspace</span>`)}${bars([38,52,45,66,57,78,62],['Mon','Tue','Wed','Thu','Fri','Sat','Sun'])}<div class="stat-foot">Use the quality page to run repeatable retrieval and intent checks.</div></div><div class="card card-pad">${cardHead('AI answer quality','Grounded answers and safe handoff')}<div class="score-row"><span>Knowledge coverage</span><strong>${fmtPct(s.groundedRate)}</strong></div><div class="progress"><span style="width:${Math.round(s.groundedRate*100)}%"></span></div><div class="score-row"><span>Handoff rate</span><strong>${fmtPct(s.handoffRate)}</strong></div><div class="progress"><span style="width:${Math.round(s.handoffRate*100)}%;background:#e3a14b"></span></div><div class="score-row"><span>Configured languages</span><strong>${s.languageCount}</strong></div><div class="progress"><span style="width:${Math.min(100,s.languageCount/70*100)}%;background:#1da68b"></span></div><p class="muted" style="font-size:10px;line-height:1.5;margin:14px 0 0">Metrics are based on local app events; they are not a claim of real-world accuracy.</p></div></div><div class="grid-2"><div class="card">${cardHead('Recent conversations','Latest customer messages',btn('Open inbox →','goto-inbox'))}<div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Intent</th><th>Language</th><th>Status</th></tr></thead><tbody>${state.data.conversations.slice(0,4).map(c=>`<tr><td><strong>${esc(c.customer)}</strong><br><span class="muted">${esc(c.channel)}</span></td><td>${esc(c.intent)}</td><td>${esc((c.language || '—').toUpperCase())}</td><td>${badge(c.status,c.status==='open'?'green':'orange')}</td></tr>`).join('')}</tbody></table></div></div><div class="card card-pad">${cardHead('Quick start','Set up a useful first version')}<div class="test-row"><div class="test-status">1</div><div><strong>Add your own policies</strong><small>Upload or paste product, shipping and refund knowledge.</small></div>${btn('Add','goto-knowledge',false,'small')}</div><div class="test-row"><div class="test-status">2</div><div><strong>Try a customer question</strong><small>Check the evidence and handoff recommendation before sending.</small></div>${btn('Try it','goto-assistant',false,'small')}</div><div class="test-row"><div class="test-status">3</div><div><strong>Run the regression suite</strong><small>Catch intent and retrieval regressions as content changes.</small></div>${btn('Run','run-tests',false,'small')}</div></div></div>`;},
inbox(){const cs=state.data.conversations;const c=getActiveConv();return `${heading('Inbox','Review customer conversations, draft a reply, and hand off when the evidence is weak.',btn('+ New conversation','new-conversation',true))}<div class="inbox-layout"><div class="card conversation-list">${cardHead('Conversations',`${cs.length} total`)}<div style="padding:0 10px 10px"><input class="search" id="conversationSearch" placeholder="Search conversations…"></div><div id="conversationRows">${cs.map(x=>`<div class="conversation-row ${c?.id===x.id?'active':''}" data-conversation="${x.id}"><div class="row-top"><strong>${esc(x.customer)}</strong><small>${esc((x.language || '—').toUpperCase())}</small></div><p>${esc(x.lastMessage)}</p><div style="margin-top:7px">${badge(x.status,x.status==='open'?'green':'orange')} <span class="muted" style="font-size:9px">${esc(x.channel)}</span></div></div>`).join('')}${cs.length?'':'<div class="empty" style="padding:20px"><strong>No conversations yet.</strong><br>New customer messages will appear here. Use “+ New conversation” to try the reply flow, or connect a channel to receive real threads.</div>'}</div></div><div class="card chat-panel"><div class="chat-header"><div><strong>${esc(c?.customer||'Select a conversation')}</strong><small>${esc(c?.channel||'')} · ${esc(c?.intent||'')} · ${esc(c?.language||'').toUpperCase()}</small></div><div>${badge(c?.status||'open',c?.status==='open'?'green':'orange')}</div></div><div class="messages">${(c?.messages||[]).map(m=>`<div class="message ${m.role==='customer'?'customer':'agent'}">${esc(m.text)}<small>${m.role==='customer'?'Customer':'Agent'} · ${new Date(m.at).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')||'<div class="empty">Select a conversation to view messages.</div>'}</div><div class="reply-box"><textarea id="replyText" placeholder="Write a reply… Keep it clear and helpful."></textarea><div class="reply-actions"><button class="btn" data-action="draft-reply">✳ Draft from knowledge</button><button class="btn primary" data-action="send-reply">Send reply ↗</button></div></div></div><aside class="card right-panel"><h4>AI assist</h4><p>Draft from store-approved knowledge and review source evidence before sending.</p><button class="btn primary" style="width:100%" data-action="draft-reply">✳ Generate reply</button><div id="inboxEvidence" style="margin-top:16px">${state.lastAnswer?renderEvidence(state.lastAnswer):'<div class="notice"><div class="notice-icon">ⓘ</div><div>Choose <strong>Draft from knowledge</strong> to see evidence and confidence.</div></div>'}</div><div class="toggle-row"><div><strong>Human handoff</strong><small>Escalate uncertain answers.</small></div><input type="checkbox" class="toggle" checked disabled></div></aside></div>`;},
assistant(){return `${heading('AI assistant','Test a customer question against your store knowledge before using it in a live channel.',`<span class="badge purple">Evidence-first</span>`)}<div class="grid-2"><div class="card card-pad"><div class="field"><label>Customer message</label><textarea id="assistantQuestion" placeholder="Example: My tracking has not updated for 5 days. What should I do?">My tracking has not updated for a few days. Can you check?</textarea><div class="help">Try a supported question, a multilingual question, or a question your knowledge base cannot answer.</div></div><div class="form-row"><div class="field"><label>Reply language</label><select id="assistantLanguage"><option value="auto">Auto-detect</option>${languages.map(l=>`<option value="${l[0]}">${l[1]} (${l[2]})</option>`).join('')}</select></div><div class="field"><label>Answer mode</label><select disabled><option>Knowledge grounded + safe fallback</option></select></div></div><button class="btn primary" id="askAssistant">Generate answer ✳</button><div class="notice" style="margin-top:14px"><div class="notice-icon">ⓘ</div><div>Answers are drafts. Verify policy and order-specific facts before sending. Unsupported questions should be handed to a person.</div></div></div><div class="card card-pad">${cardHead('Generated response','Answer, evidence and safety recommendation')}<div id="assistantResult">${state.lastAnswer?renderAnswer(state.lastAnswer):'<div class="empty">Your answer will appear here, with evidence references and a confidence score.</div>'}</div></div></div><div class="card card-pad" style="margin-top:16px">${cardHead('Suggested test prompts','Quickly sample common seller support intents')}<div class="grid-3">${[['Shipping','Where is my order? Tracking has not moved.'],['Returns','Can I return an unused item and get a refund?'],['Warranty','What is the warranty if the product is faulty?']].map(([t,q])=>`<button class="btn" data-prompt="${esc(q)}">${t} · Try prompt</button>`).join('')}</div></div>`;},
knowledge(){const items=state.data.knowledge.filter(x=>(x.title+' '+x.content+' '+(x.tags||[]).join(' ')).toLowerCase().includes(state.knowledgeSearch.toLowerCase()));return `${heading('Knowledge base','Your store’s source of truth. Add approved product details, policies, FAQs and support procedures.',btn('+ Add article','show-kb-form',true))}<div class="notice" style="margin-bottom:16px"><div class="notice-icon">▧</div><div><strong>Evidence before eloquence.</strong> Better source content usually improves support more reliably than expanding prompts alone. Keep each article current, scoped and approved.</div></div><div class="card card-pad" id="kbForm" style="display:none;margin-bottom:16px">${cardHead('Add knowledge article','Plain text, FAQ or policy; maximum 500 KB')}<form id="knowledgeForm"><div class="form-row"><div class="field"><label>Article title *</label><input name="title" required placeholder="e.g. International shipping policy"></div><div class="field"><label>Content type</label><select name="type"><option value="faq">FAQ</option><option value="policy">Policy</option><option value="product">Product information</option><option value="procedure">Support procedure</option><option value="article">Article</option></select></div></div><div class="form-row"><div class="field"><label>Language</label><select name="language">${languages.map(l=>`<option value="${l[0]}">${l[1]}</option>`).join('')}</select></div><div class="field"><label>Tags (comma separated)</label><input name="tags" placeholder="shipping, tracking, international"></div></div><div class="field"><label>Approved content *</label><textarea name="content" required style="min-height:130px" placeholder="State what is confirmed, exceptions, and when to escalate."></textarea></div><div class="heading-actions"><button class="btn primary" type="submit">Save article</button><button class="btn" type="button" data-action="hide-kb-form">Cancel</button></div></form></div><div class="filter-row"><input class="search" id="kbSearch" placeholder="Search title, content or tags…" value="${esc(state.knowledgeSearch)}"><span class="muted">${items.length} articles</span><button class="btn" data-action="export-data">Export data</button></div><div class="kb-list">${items.map(x=>`<div class="kb-card"><div class="kb-card-top"><div class="file-icon">▤</div><div style="min-width:0;flex:1"><h4>${esc(x.title)}</h4><p>${esc(x.content.slice(0,210))}${x.content.length>210?'…':''}</p></div></div><div class="kb-meta">${badge(x.type,'purple')}${badge(x.language.toUpperCase(),'blue')} ${(x.tags||[]).slice(0,3).map(t=>badge(esc(t))).join('')}<div class="kb-actions"><button class="btn small" data-action="copy-kb" data-id="${x.id}">Copy</button>${x.id.startsWith('kb_demo_')?'':`<button class="btn small danger" data-action="delete-kb" data-id="${x.id}">Delete</button>`}</div></div></div>`).join('')||'<div class="card empty">No matching articles. Add content or change the search.</div>'}</div><div class="card card-pad" style="margin-top:16px">${cardHead('Bulk import','Import .txt, .md, .json or .csv as one article at a time')}<div class="field"><label>Select a text-based file</label><input type="file" id="knowledgeFile" accept=".txt,.md,.json,.csv,.html,text/plain,text/markdown,application/json,text/csv"><div class="help">Files are read in your browser and submitted as text. PDFs and DOCX require a separate parser integration in this MVP.</div></div><button class="btn" data-action="import-file">Read file into article form</button></div>`;},
glossary(){const items=state.data.glossary.filter(x=>(x.source+' '+x.notes).toLowerCase().includes(state.glossarySearch.toLowerCase()));return `${heading('Terminology & brand voice','Keep product names, abbreviations and policy terms consistent across languages.',btn('+ Add term','show-term-form',true))}<div class="grid-2"><div class="card card-pad" id="termForm" style="display:none">${cardHead('Add approved term')}<form id="termAddForm"><div class="field"><label>Source term *</label><input name="source" required placeholder="e.g. Express Dispatch"></div><div class="field"><label>Approved translations (JSON)</label><textarea name="preferred" placeholder='{"en":"Express Dispatch","es":"Envío exprés"}'></textarea></div><div class="field"><label>Usage notes</label><textarea name="notes" placeholder="Never promise a delivery date without order data."></textarea></div><button class="btn primary" type="submit">Save term</button> <button class="btn" type="button" data-action="hide-term-form">Cancel</button></form></div><div class="card card-pad">${cardHead('Glossary coverage','Languages with preferred terms')}<div class="stats-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${stat('Approved terms',state.data.glossary.length,'Store-level terminology','文')}${stat('Language variants',new Set(state.data.glossary.flatMap(x=>Object.keys(x.preferred||{}))).size,'Across current glossary','◎')}</div><p class="muted" style="line-height:1.6">A glossary is a terminology constraint, not a translation model. Validate every customer-facing language with native or expert review.</p></div></div><div class="filter-row" style="margin-top:16px"><input id="termSearch" class="search" placeholder="Search terminology…" value="${esc(state.glossarySearch)}"></div><div class="card table-wrap"><table class="table"><thead><tr><th>Source term</th><th>English</th><th>Spanish</th><th>French</th><th>Chinese</th><th>Usage note</th></tr></thead><tbody>${items.map(x=>`<tr><td><strong>${esc(x.source)}</strong></td><td>${esc(x.preferred?.en||'—')}</td><td>${esc(x.preferred?.es||'—')}</td><td>${esc(x.preferred?.fr||'—')}</td><td>${esc(x.preferred?.zh||'—')}</td><td>${esc(x.notes||'—')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty" style="padding:22px"><strong>No approved terms yet.</strong><br>Add product names, abbreviations or policy terms so answers stay consistent across languages. Start with “+ Add term”; if you expected results, clear the search box above.</td></tr>'}</tbody></table></div>`;},
channels(){return `${heading('Channels','Connect the support workflow to the places customers already contact you. These cards are setup guides, not claims of live provider connectivity.')}<div class="notice" style="margin-bottom:16px"><div class="notice-icon">⌘</div><div><strong>Integration status:</strong> this MVP does not yet send or receive real messages from third-party channels. Use the local inbox for testing, then add provider OAuth, webhooks, signature verification and retry queues.</div></div><div class="grid-3">${[['◉','Website chat','Embed a lightweight widget on your storefront.','Ready for setup','purple'],['✉','Email support','Connect an inbound mailbox through a provider API.','Integration needed','orange'],['▣','WhatsApp Business','Use official Business Platform APIs and approved templates.','Integration needed','orange'],['◎','Instagram messages','Connect through Meta’s approved messaging permissions.','Integration needed','orange'],['▤','Helpdesk import','Import conversations from CSV or your existing helpdesk.','CSV workflow','green'],['⌁','Custom webhook','Receive signed events from your backend or commerce platform.','Developer setup','blue']].map(([ic,t,d,s,cl])=>`<div class="card channel-card"><div class="channel-icon">${ic}</div><h3>${t}</h3><p>${d}</p><div class="channel-foot">${badge(s,cl)}<button class="btn small" data-action="channel-info" data-name="${t}">Configure →</button></div></div>`).join('')}</div><div class="card card-pad" style="margin-top:16px">${cardHead('Website widget starter','A safe first integration point')}<p class="muted" style="font-size:11px;line-height:1.6">When you build the production widget, authenticate tenant identity server-side, rate-limit requests, sanitize content, and never expose an LLM or provider secret in browser code.</p><div class="code-box">POST /api/chat<br>{ "message": "Where is my order?", "language": "en" }<br><br>Response includes: answer, confidence, grounded, needsHuman, evidence[]</div><div style="margin-top:13px">${btn('Open API health ↗','api-health')}</div></div>`;},
languages(){const active=new Set(state.data.settings.supportedLanguages||[]);return `${heading('Languages','Configure language coverage. Language codes are supported in the app, but translation quality must be evaluated per language and domain.',btn('Save language selection','save-languages',true))}<div class="stats-grid">${stat('Enabled languages',active.size,'Current workspace setting','◎')}${stat('Available in selector',languages.length,'Starter list; add codes as needed','文')}${stat('Glossary entries',state.data.glossary.length,'Term mappings available','▤')}${stat('Default language',(state.data.settings.defaultLanguage||'en').toUpperCase(),'Fallback when not detected','⚑')}</div><div class="notice" style="margin-bottom:15px"><div class="notice-icon">!</div><div><strong>Important:</strong> do not “distill English into all languages” and assume equivalence. Use English as an authoring pivot if helpful, but retrieve source facts independent of language, preserve identifiers, use localized query expansion only as a secondary aid, and run per-language golden tests.</div></div><div class="card card-pad"><div class="card-head"><div><h3>Language coverage</h3><p>Toggle starter languages for this workspace.</p></div><input class="search" id="languageSearch" style="max-width:220px" placeholder="Find a language…"></div><div class="language-grid" id="languageGrid">${languages.map(l=>`<label class="language-card" data-lang-search="${l[1].toLowerCase()} ${l[0]}"><span class="flag">${l[2]}</span><span style="flex:1"><strong>${l[1]}</strong><small>${l[0]}</small></span><input class="toggle language-toggle" type="checkbox" value="${l[0]}" ${active.has(l[0])?'checked':''}></label>`).join('')}</div></div><div class="card card-pad" style="margin-top:16px">${cardHead('Recommended language pipeline')}<div class="grid-3"><div><strong>1. Detect</strong><p class="muted">Detect the customer’s language, but allow manual override for short or ambiguous messages.</p></div><div><strong>2. Retrieve</strong><p class="muted">Search approved source facts by multilingual embeddings plus lexical terms, IDs and glossary aliases.</p></div><div><strong>3. Validate</strong><p class="muted">Test intent, evidence, terminology and safety separately for each target language.</p></div></div></div>`;},
analytics(){const s=state.data.stats;const events=state.data;return `${heading('Analytics','Measure the customer-support system, not just how fluent the answers sound.',btn('Export raw data','export-data',true))}${s.answers?'':'<div class="notice" style="margin-bottom:16px"><div class="notice-icon">▥</div><div><strong>No answer events yet — every metric below is zero.</strong> Analytics is built from local answer events. Open <strong>AI assistant</strong> and generate one reply, or send a message from <strong>Inbox</strong>; this page populates immediately.</div></div>'}<div class="stats-grid">${stat('Generated answers',s.answers,'Recorded locally','✳')}${stat('Evidence coverage',fmtPct(s.groundedRate),'Answers with retrieval hits','▧')}${stat('Human handoff',fmtPct(s.handoffRate),'Needs review or no evidence','↗')}${stat('Mean confidence',fmtPct(s.averageConfidence),'Model/fallback self-score; not calibrated','◉')}</div><div class="grid-2"><div class="card card-pad">${cardHead('Answer pipeline','Local event counts')}<div class="score-row"><span>Grounded answers</span><strong>${fmtPct(s.groundedRate)}</strong></div><div class="progress"><span style="width:${Math.round(s.groundedRate*100)}%"></span></div><div class="score-row"><span>Escalation / handoff</span><strong>${fmtPct(s.handoffRate)}</strong></div><div class="progress"><span style="width:${Math.round(s.handoffRate*100)}%;background:#e5a24c"></span></div><div class="score-row"><span>Knowledge articles</span><strong>${s.knowledgeCount}</strong></div><div class="progress"><span style="width:${Math.min(100,s.knowledgeCount*7)}%;background:#1b9e8c"></span></div><p class="muted" style="font-size:10px;line-height:1.5">These metrics describe app behavior only. Do not treat model confidence as a probability until calibrated against labeled cases.</p></div><div class="card card-pad">${cardHead('Quality scorecard','Metrics to track in production')}<div class="test-row"><div class="test-status">✓</div><div><strong>Intent accuracy</strong><small>Correct primary intent and multi-intent handling.</small></div></div><div class="test-row"><div class="test-status">✓</div><div><strong>Evidence faithfulness</strong><small>Every policy claim supported by retrieved store content.</small></div></div><div class="test-row"><div class="test-status">✓</div><div><strong>Resolution and reopen rate</strong><small>Customer outcome, not only answer generation.</small></div></div><div class="test-row"><div class="test-status">✓</div><div><strong>Latency and cost per resolution</strong><small>Track model time, retries, tokens, and human handling cost.</small></div></div></div></div><div class="card table-wrap">${cardHead('Recent answer events','Most recent local evaluations')}<table class="table"><thead><tr><th>Event</th><th>Language</th><th>Intent</th><th>Confidence</th><th>Evidence</th><th>Handoff</th></tr></thead><tbody>${(state.data.recentEvents||[]).filter(e=>e.type==='answer_generated').slice(0,15).map(e=>`<tr><td>${new Date(e.at).toLocaleString()}</td><td>${esc(e.language||'—')}</td><td>${esc(e.intent||'—')}</td><td>${fmtPct(e.confidence)}</td><td>${e.grounded?badge('Grounded','green'):badge('No match','red')}</td><td>${e.needsHuman?badge('Review','orange'):badge('No','green')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No answer events yet. Test a question in AI assistant.</td></tr>'}</tbody></table></div>`;},
tests(){const runs=state.data.testRuns||[];return `${heading('Quality & regression tests','Run repeatable baseline checks before changing prompts, models, or knowledge content.',btn('Run test suite ▶','run-tests',true))}<div class="notice" style="margin-bottom:16px"><div class="notice-icon">✓</div><div><strong>Regression gate:</strong> the included suite tests basic intent routing and retrieval coverage. It is a starter suite, not proof of production-grade accuracy, multilingual parity, or security. Expand it with labeled real customer cases.</div></div><div class="stats-grid">${stat('Test cases in baseline','5','Small deterministic smoke suite','✓')}${stat('Latest pass rate',runs.length?`${Math.round(runs[0].passed/runs[0].total*100)}%`:'—',runs.length?`${runs[0].passed} / ${runs[0].total} passed`:'No run yet','◉')}${stat('Knowledge items',state.data.knowledge.length,'Current retrieval corpus','▧')}${stat('Saved runs',runs.length,'Stored in local JSON','▤')}</div><div class="grid-2"><div class="card card-pad">${cardHead('Recommended production gates')}<div class="test-row"><div class="test-status">1</div><div><strong>Retrieval relevance</strong><small>Expected source appears in top-k for each golden question.</small></div></div><div class="test-row"><div class="test-status">2</div><div><strong>Faithfulness / unsupported claims</strong><small>Answer statements are supported by source excerpts; unsupported cases abstain.</small></div></div><div class="test-row"><div class="test-status">3</div><div><strong>Multilingual parity</strong><small>Golden sets for every launched language, not only English.</small></div></div><div class="test-row"><div class="test-status">4</div><div><strong>Adversarial and privacy tests</strong><small>Prompt injection, PII leakage, tenant boundary and malicious knowledge documents.</small></div></div><div class="test-row"><div class="test-status">5</div><div><strong>Browser end-to-end tests</strong><small>Login, upload, reply, handoff, export, responsive layouts and failure paths.</small></div></div></div><div class="card card-pad">${cardHead('Latest test run',runs[0]?new Date(runs[0].at).toLocaleString():'No run yet')}<div id="latestRun">${runs[0]?renderRun(runs[0]):'<div class="empty" style="padding:18px"><strong>No test run yet.</strong><br>The baseline checks intent routing and retrieval coverage. Press <strong>Run test suite ▶</strong> above to record your first result — a few seconds, no setup needed.</div>'}</div></div></div><div class="card card-pad" style="margin-top:16px">${cardHead('Run history')}<div id="runHistory">${runs.map(r=>`<div class="test-row"><div class="test-status ${r.passed<r.total?'fail':''}">${r.passed===r.total?'✓':'!'}</div><div style="flex:1"><strong>${r.passed}/${r.total} passed</strong><small>${new Date(r.at).toLocaleString()}</small></div>${badge(r.passed===r.total?'PASS':'REVIEW',r.passed===r.total?'green':'orange')}</div>`).join('')||'<div class="empty" style="padding:18px"><strong>History is empty because no run has completed.</strong><br>Each run is stored with pass/fail counts so regressions after prompt, model or knowledge changes are easy to spot.</div>'}</div></div>`;},
growth(){const enabled=state.data.settings.adsEnabled;return `${heading('Seller briefings','Useful industry updates for sellers. Sponsored placements are explicitly labeled and must never affect the assistant’s answers.',btn('Manage ad settings','goto-settings',true))}<div class="upgrade-banner"><div><h3>More signal, less noise.</h3><p>Track marketplace changes, fulfillment updates and practical seller operations in one place.</p></div><button class="btn" data-action="goto-settings">Explore ad-free plan →</button></div><div class="notice" style="margin-bottom:16px"><div class="notice-icon">ⓘ</div><div><strong>Advertising transparency:</strong> ads must be clearly marked “Sponsored”, must not imitate system alerts, and must not require accidental clicks or artificial watch time. Revenue should come from legitimate impressions or disclosed affiliate actions, subject to local law and platform policies.</div></div><div class="briefing-grid">${[['↗','Marketplace changes to watch','A practical checklist for keeping product listings, policies and delivery promises current.','Sponsored · Example placement'],['▦','Shipping and returns benchmark','Compare your support workflow against a simple operations checklist.','Editorial · Sample content'],['◉','Short video: reduce repetitive tickets','Three workflow ideas for handling common product and order questions.','Sponsored · Example placement']].map(([ic,t,d,label],i)=>`<div class="card brief-card"><div class="brief-art">${ic}</div><div class="brief-body">${label.startsWith('Sponsored')?'<span class="sponsored">Sponsored</span>':'<span class="badge green">Editorial</span>'}<h3>${t}</h3><p>${d}</p><div class="brief-meta"><span>4 min read</span><span>${i===2?'▶ Watch preview':'Read briefing →'}</span></div></div></div>`).join('')}</div><div class="card card-pad" style="margin-top:16px">${cardHead('Free plan usage','Transparent limits and upgrade options')}<div class="grid-2 equal"><div><div class="score-row"><span>Monthly AI replies</span><strong>68 / ${state.data.settings.freeMonthlyReplies||200}</strong></div><div class="progress"><span style="width:${Math.min(100,68/(state.data.settings.freeMonthlyReplies||200)*100)}%"></span></div><p class="muted" style="font-size:10px;line-height:1.5">Sample UI usage numbers for the prototype. Production usage must be calculated from actual metered events.</p></div><div><strong>Want a quieter workspace?</strong><p class="muted" style="font-size:10px;line-height:1.6">A paid plan can remove sponsored placements and increase usage. Do not make the free experience intentionally obstructive or conceal advertising labels.</p>${btn('Review plan settings','goto-settings',true)}</div></div></div>`;},
settings(){const s=state.data.settings;return `${heading('Settings','Configure your store, model connection, safe answer behavior and transparent free-plan monetization.',btn('Export workspace JSON','export-data'))}${profileCard()}<div class="grid-2"><div class="card card-pad">${cardHead('Store profile','Workspace-level defaults')}<form id="settingsForm"><div class="field"><label>Store / workspace name</label><input name="storeName" value="${esc(s.storeName)}"></div><div class="form-row"><div class="field"><label>Default language</label><select name="defaultLanguage">${languages.map(l=>`<option value="${l[0]}" ${s.defaultLanguage===l[0]?'selected':''}>${l[1]}</option>`).join('')}</select></div><div class="field"><label>Confidence threshold (0–1)</label><input name="confidenceThreshold" type="number" min="0" max="1" step="0.05" value="${s.confidenceThreshold}"></div></div><div class="toggle-row"><div><strong>Require knowledge evidence</strong><small>Prefer abstention when no source is found.</small></div><input class="toggle" name="requireEvidence" type="checkbox" ${s.requireEvidence?'checked':''}></div><div class="toggle-row"><div><strong>Human handoff enabled</strong><small>Flag uncertain or unsupported answers for review.</small></div><input class="toggle" name="humanHandoff" type="checkbox" ${s.humanHandoff?'checked':''}></div><div class="toggle-row"><div><strong>Ollama local model enabled</strong><small>Requires OLLAMA_URL, model pull and server reachability.</small></div><input class="toggle" name="ollamaEnabled" type="checkbox" ${s.ollamaEnabled?'checked':''}></div><button class="btn primary" type="submit" style="margin-top:15px">Save settings</button></form></div><div class="card card-pad">${cardHead('Model and deployment','Local-first setup')}<div class="notice"><div class="notice-icon">⌘</div><div>Ollama is called from the server, not the browser. This MVP uses a lexical retrieval baseline and safe fallback when no model is configured.</div></div><div class="field" style="margin-top:14px"><label>Ollama URL (server environment)</label><input readonly value="${esc(location.protocol==='https:'?'Configure on server via OLLAMA_URL':'http://127.0.0.1:11434')}"></div><div class="field"><label>Model (server environment)</label><input readonly value="OLLAMA_MODEL=qwen2.5:7b"></div><div class="code-box"># .env / environment variables<br>OLLAMA_URL=http://127.0.0.1:11434<br>OLLAMA_MODEL=qwen2.5:7b<br>OLLAMA_TIMEOUT_MS=25000<br>APP_API_KEY=replace-with-long-random-secret</div><p class="muted" style="font-size:10px;line-height:1.5">For public deployment, add authentication, tenant isolation, HTTPS, reverse proxy limits, backups, audit logs and abuse protection before exposing customer data.</p></div></div><div class="grid-2" style="margin-top:16px"><div class="card card-pad">${cardHead('Free plan and ads','Never use hidden or deceptive placements')}<form id="adsForm"><div class="toggle-row"><div><strong>Sponsored seller briefings</strong><small>Show clearly labeled sponsor cards on the briefing page.</small></div><input class="toggle" name="adsEnabled" type="checkbox" ${s.adsEnabled?'checked':''}></div><div class="field" style="margin-top:13px"><label>Disclosure text</label><textarea name="adDisclosure">${esc(s.adDisclosure||'')}</textarea></div><div class="field"><label>Free monthly reply allowance</label><input name="freeMonthlyReplies" type="number" min="0" max="100000" value="${s.freeMonthlyReplies}"></div><button class="btn primary" type="submit">Save monetization settings</button></form></div><div class="card card-pad">${cardHead('Data and privacy')}<p class="muted" style="font-size:11px;line-height:1.7">This MVP stores workspace data in a local JSON file. It is for development and controlled testing, not production multi-tenant use. Do not upload sensitive customer records. Before launch, implement tenant-aware database storage, data retention, deletion/export flows, encryption and least-privilege access.</p><button class="btn" data-action="export-data">Download workspace JSON</button> <button class="btn danger" data-action="reset-demo">Reset demo data</button></div></div>`;}
};
function renderEvidence(answer){return `${(answer.evidence||[]).map(e=>`<div class="evidence-item"><strong>${esc(e.title)}</strong><small>Match score ${(e.score*100).toFixed(0)}% · ${esc((e.language || '—').toUpperCase())}</small></div>`).join('')||'<div class="empty">No matching evidence found.</div>'}<div class="score-row"><span>Confidence (uncalibrated)</span><strong>${fmtPct(answer.confidence)}</strong></div><div class="progress"><span style="width:${Math.round(answer.confidence*100)}%"></span></div><div style="margin-top:12px">${answer.needsHuman?badge('Human review recommended','orange'):badge('Draft ready for review','green')}</div>`;}
function renderAnswer(a){return `<div class="notice" style="margin-bottom:12px"><div class="notice-icon">✳</div><div><strong>Draft answer</strong><div style="margin-top:7px;color:#5b6578;line-height:1.65">${esc(a.answer)}</div></div></div><div class="score-row"><span>Detected intent</span><strong>${esc(a.intent)}</strong></div><div class="score-row"><span>Answer mode</span><strong>${esc(a.model)}</strong></div>${renderEvidence(a)}<div style="display:flex;gap:7px;margin-top:13px;flex-wrap:wrap"><button class="btn small" data-action="copy-answer">Copy answer</button><button class="btn small" data-action="feedback-good">Helpful</button><button class="btn small" data-action="feedback-bad">Needs correction</button></div>`;}
function renderRun(run){return `${badge(run.passed===run.total?'ALL PASS':'REVIEW',run.passed===run.total?'green':'orange')}<div style="margin-top:10px">${run.results.map(r=>`<div class="test-row"><div class="test-status ${r.pass?'':'fail'}">${r.pass?'✓':'!'}</div><div><strong>${esc(r.name)}</strong><small>Expected: ${esc(r.expected)} · Actual: ${esc(r.actualIntent)} · Evidence: ${r.grounded?'yes':'no'}</small></div></div>`).join('')}</div>`;}
async function reload(){const [b,m,t]=await Promise.all([api('/api/bootstrap'),api('/api/metrics'),api('/api/tests')]);state.data={...b,recentEvents:m.recentEvents,testRuns:t.runs,stats:m.stats};if(!state.activeConversation&&state.data.conversations.length)state.activeConversation=state.data.conversations[0].id;render();}
function go(page){state.page=page;render();window.scrollTo({top:0,behavior:'smooth'});}
function wirePage(){
 document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>go(el.dataset.page));
 document.querySelectorAll('[data-prompt]').forEach(el=>el.onclick=()=>{$('#assistantQuestion').value=el.dataset.prompt;});
 document.querySelectorAll('[data-conversation]').forEach(el=>el.onclick=()=>{state.activeConversation=el.dataset.conversation;state.lastAnswer=null;render();});
 const ask=$('#askAssistant');if(ask)ask.onclick=async()=>{const message=$('#assistantQuestion').value.trim();if(!message)return toast('Enter a customer message first.');ask.disabled=true;ask.textContent='Generating…';try{const language=$('#assistantLanguage').value;const r=await api('/api/chat',{method:'POST',body:JSON.stringify({message,language:language==='auto'?undefined:language})});state.lastAnswer=r.result;await reload();go('assistant');}catch(e){toast(e.message);}finally{ask.disabled=false;ask.textContent='Generate answer ✳';}};
 const kbSearch=$('#kbSearch');if(kbSearch)kbSearch.oninput=e=>{state.knowledgeSearch=e.target.value;const pos=e.target.selectionStart;render();const n=$('#kbSearch');n.focus();n.setSelectionRange(pos,pos);};
 const termSearch=$('#termSearch');if(termSearch)termSearch.oninput=e=>{state.glossarySearch=e.target.value;const pos=e.target.selectionStart;render();const n=$('#termSearch');n.focus();n.setSelectionRange(pos,pos);};
 const langSearch=$('#languageSearch');if(langSearch)langSearch.oninput=()=>document.querySelectorAll('[data-lang-search]').forEach(el=>el.classList.toggle('hidden',!el.dataset.langSearch.includes(langSearch.value.toLowerCase())));
 const convSearch=$('#conversationSearch');if(convSearch)convSearch.oninput=()=>document.querySelectorAll('[data-conversation]').forEach(el=>el.classList.toggle('hidden',!el.textContent.toLowerCase().includes(convSearch.value.toLowerCase())));
 const kf=$('#knowledgeForm');if(kf)kf.onsubmit=async e=>{e.preventDefault();const fd=new FormData(kf);try{await api('/api/knowledge',{method:'POST',body:JSON.stringify({title:fd.get('title'),type:fd.get('type'),language:fd.get('language'),tags:String(fd.get('tags')).split(',').map(x=>x.trim()).filter(Boolean),content:fd.get('content'),source_id:'manual_editor'})});state.knowledgeSearch='';await reload();toast('Knowledge article saved as draft (pending review).');}catch(err){toast(err.message);}};
 const tf=$('#termAddForm');if(tf)tf.onsubmit=async e=>{e.preventDefault();const fd=new FormData(tf);let preferred={};try{preferred=JSON.parse(fd.get('preferred')||'{}');}catch{return toast('Translations must be valid JSON.');}try{await api('/api/glossary',{method:'POST',body:JSON.stringify({source:fd.get('source'),preferred,notes:fd.get('notes')})});await reload();toast('Term saved.');}catch(err){toast(err.message);}};
 const sf=$('#settingsForm');if(sf)sf.onsubmit=async e=>{e.preventDefault();const fd=new FormData(sf);const data={storeName:fd.get('storeName'),defaultLanguage:fd.get('defaultLanguage'),confidenceThreshold:Number(fd.get('confidenceThreshold')),requireEvidence:sf.elements.requireEvidence.checked,humanHandoff:sf.elements.humanHandoff.checked,ollamaEnabled:sf.elements.ollamaEnabled.checked};try{await api('/api/settings',{method:'PATCH',body:JSON.stringify(data)});await reload();toast('Settings saved.');}catch(err){toast(err.message);}}; const pfW=$('#profileForm');if(pfW)pfW.onsubmit=async e=>{e.preventDefault();const fd=new FormData(pfW);const split=v=>String(v||'').split(',').map(x=>x.trim()).filter(Boolean);try{await api('/api/v1/tenant-profile',{method:'PUT',body:JSON.stringify({business_name:fd.get('business_name'),monthly_revenue:fd.get('monthly_revenue'),categories:fd.get('categories'),markets:split(fd.get('markets')),platforms:split(fd.get('platforms')),team_size:fd.get('team_size')?Number(fd.get('team_size')):undefined,goals:fd.get('goals')})});await reload();toast('经营档案已保存，AI 回答会带上这些上下文。');}catch(err){toast(err.message);}}; const paW=$('#profileAnalyze');if(paW)paW.onclick=async()=>{paW.disabled=true;paW.textContent='诊断中…';try{const r=await api('/api/v1/tenant-profile/analyze',{method:'POST',body:'{}'});const box=$('#profileAi');if(box)box.innerHTML='<div class="notice"><div class="notice-icon">✦</div><div><strong>AI 诊断：</strong>'+esc(r.summary||'')+'<ul>'+(r.actions||[]).map(a=>'<li>'+esc(a)+'</li>').join('')+'</ul></div></div>';toast('AI 诊断完成');}catch(err){toast(err.message);}finally{paW.disabled=false;paW.textContent='AI 诊断';}};
 const af=$('#adsForm');if(af)af.onsubmit=async e=>{e.preventDefault();const fd=new FormData(af);try{await api('/api/settings',{method:'PATCH',body:JSON.stringify({adsEnabled:af.elements.adsEnabled.checked,adDisclosure:fd.get('adDisclosure'),freeMonthlyReplies:Number(fd.get('freeMonthlyReplies'))})});await reload();toast('Monetization settings saved.');}catch(err){toast(err.message);}};
 document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action,el.dataset.id,el.dataset.name));
 const file=$('#knowledgeFile');if(file)file.onchange=()=>{if(file.files?.[0])toast(`Selected ${file.files[0].name}. Click “Read file into article form” to import its text.`);};
}
async function action(name,id,nameArg){try{switch(name){case'goto-knowledge':go('knowledge');$('#kbForm').style.display='block';break;case'goto-inbox':go('inbox');break;case'goto-assistant':go('assistant');break;case'goto-settings':go('settings');break;case'run-tests':{const r=await api('/api/test/run',{method:'POST',body:'{}'});await reload();go('tests');toast(`Regression run: ${r.run.passed}/${r.run.total} passed.`);break;}case'show-kb-form':$('#kbForm').style.display='block';$('#kbForm').scrollIntoView({behavior:'smooth'});break;case'hide-kb-form':$('#kbForm').style.display='none';break;case'show-term-form':$('#termForm').style.display='block';break;case'hide-term-form':$('#termForm').style.display='none';break;case'delete-kb':if(!confirm('Delete this knowledge article?'))break;await api('/api/knowledge/'+encodeURIComponent(id),{method:'DELETE'});await reload();toast('Article deleted.');break;case'copy-kb':{const item=state.data.knowledge.find(x=>x.id===id);await navigator.clipboard.writeText(`${item.title}\n\n${item.content}`);toast('Article copied.');break;}case'draft-reply':{const c=getActiveConv();if(!c)return toast('Choose a conversation.');const r=await api('/api/chat',{method:'POST',body:JSON.stringify({message:c.lastMessage,language:c.language})});state.lastAnswer=r.result;render();const target=$('#replyText');if(target)target.value=r.result.answer;const ev=$('#inboxEvidence');if(ev)ev.innerHTML=renderEvidence(r.result);toast(r.result.needsHuman?'Draft created; human review recommended.':'Draft created; verify before sending.');break;}case'send-reply':{const c=getActiveConv();const text=$('#replyText')?.value.trim();if(!c||!text)return toast('Choose a conversation and write a reply.');await api(`/api/conversations/${c.id}/reply`,{method:'POST',body:JSON.stringify({message:text,status:'pending'})});state.activeConversation=c.id;await reload();toast('Reply saved to local conversation history. No external channel message was sent.');break;}case'new-conversation':{const message=prompt('Enter the first customer message:');if(!message?.trim())break;const customer=prompt('Customer display name (optional):')||'New customer';const r=await api('/api/conversations',{method:'POST',body:JSON.stringify({message,customer,channel:'Website'})});state.activeConversation=r.item.id;await reload();go('inbox');break;}case'export-data':{const d=await api('/api/export');const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='relaydesk-workspace-export.json';a.click();URL.revokeObjectURL(a.href);toast('Workspace export downloaded.');break;}case'copy-answer':if(state.lastAnswer){await navigator.clipboard.writeText(state.lastAnswer.answer);toast('Answer copied.');}break;case'feedback-good':case'feedback-bad':if(state.lastAnswer){await api('/api/feedback',{method:'POST',body:JSON.stringify({answerId:state.lastAnswer.id,rating:name==='feedback-good'?'helpful':'not_helpful'})});await reload();toast('Feedback recorded.');}break;case'api-health':window.open('/api/health','_blank','noopener');break;case'channel-info':toast(`${nameArg}: provider credentials and webhook integration are not included in this MVP.`);break;case'save-languages':{const selected=[...document.querySelectorAll('.language-toggle:checked')].map(x=>x.value);if(!selected.length)return toast('Select at least one language.');await api('/api/settings',{method:'PATCH',body:JSON.stringify({supportedLanguages:selected})});await reload();toast(`${selected.length} languages saved.`);break;}case'import-file':{const f=$('#knowledgeFile')?.files?.[0];if(!f)return toast('Choose a text file first.');if(f.size>500000)return toast('File exceeds 500 KB.');const content=await f.text();const title=f.name.replace(/\.[^.]+$/,'');$('#kbForm').style.display='block';$('#knowledgeForm').elements.title.value=title;$('#knowledgeForm').elements.content.value=content;$('#kbForm').scrollIntoView({behavior:'smooth'});toast('Text loaded into the article form. Review it, then save.');break;}case'reset-demo':if(!confirm('This deletes local changes and restores the demo seed data. Continue?'))break;toast('For safety, delete the .data/store.json file while the server is stopped to reset demo data, then restart.');break;}}
 catch(e){toast(e.message||'Action failed.');}}
wirePage();
(async()=>{
  if(!localStorage.getItem(TOKEN_KEY)){authGate();return;}
  try{await reload();}
  catch(e){
    if(e.auth){authGate('登录已过期，请重新登录 / Session expired; sign in again.');return;}
    $('#page').innerHTML=`<div class="card card-pad"><h2>Unable to connect to RelayDesk API</h2><p>${esc(e.message)}</p><p>Start the app with <code>npm start</code> and reload this page.</p></div>`;
  }
})();
